package cn.sixnine.filmlog.verification;
import android.app.Instrumentation;
import android.content.*;
import android.database.*;
import android.database.sqlite.*;
import android.os.Bundle;
import java.io.*;
import java.util.*;
/** Signed read-only acceptance against the actual installed app, not synthetic test storage. */
public final class UpgradeInstrumentation extends Instrumentation {
 private boolean snapshot;
 @Override public void onCreate(Bundle args){super.onCreate(args);snapshot="true".equals(args.getString("snapshot","false"));start();}
 private long count(SQLiteDatabase db,String sql){try(Cursor c=db.rawQuery(sql,null)){if(!c.moveToFirst())throw new AssertionError("no count");return c.getLong(0);}}
 @Override public void onStart(){Bundle out=new Bundle();try{Context c=getTargetContext();if(!c.getPackageName().equals("cn.sixnine.filmlog"))throw new AssertionError("wrong target");String workspace=c.getSharedPreferences("workspace-registry",0).getString("active","guest");if(!workspace.equals("guest"))UUID.fromString(workspace);String dbName=workspace.equals("guest")?"film-log.db":"workspace-"+workspace+"-film-log.db";File path=c.getDatabasePath(dbName);if(!path.isFile())throw new AssertionError("expected existing database");try(SQLiteDatabase db=SQLiteDatabase.openDatabase(path.getPath(),null,SQLiteDatabase.OPEN_READONLY)){try(Cursor check=db.rawQuery("PRAGMA quick_check",null)){if(!check.moveToFirst()||!check.getString(0).equals("ok"))throw new AssertionError("database integrity");}long rolls=count(db,"SELECT COUNT(*) FROM rolls"),shots=count(db,"SELECT COUNT(*) FROM shots"),scans=count(db,"SELECT COUNT(*) FROM scans"),wrongTime=count(db,"SELECT COUNT(*) FROM shots WHERE captured_at<>tapped_at+offset_seconds*1000"),orphans=count(db,"SELECT COUNT(*) FROM shots WHERE roll_id NOT IN (SELECT id FROM rolls)");if(wrongTime!=0||orphans!=0)throw new AssertionError("time or roll relation broken");File files=workspace.equals("guest")?c.getFilesDir():new File(new File(c.getFilesDir(),"workspaces"),workspace);int missing=0;try(Cursor entries=db.rawQuery("SELECT id FROM scans",null)){while(entries.moveToNext()){String id=entries.getString(0);UUID.fromString(id);if(!new File(new File(files,"scans"),id+".jpg").isFile())missing++;}}if(missing!=0)throw new AssertionError("missing scan originals: "+missing);String detail="";if(snapshot){org.json.JSONObject data=new org.json.JSONObject();for(String table:new String[]{"catalog_entries","film_batches","rolls","shots","scans","roll_details","stock_history","reference_photos","film_stocks"}){org.json.JSONArray rows=new org.json.JSONArray();try(Cursor row=db.rawQuery("SELECT * FROM "+table,null)){while(row.moveToNext()){org.json.JSONObject values=new org.json.JSONObject();for(int i=0;i<row.getColumnCount();i++){Object value;switch(row.getType(i)){case Cursor.FIELD_TYPE_NULL:value=org.json.JSONObject.NULL;break;case Cursor.FIELD_TYPE_INTEGER:value=row.getLong(i);break;case Cursor.FIELD_TYPE_FLOAT:value=row.getDouble(i);break;default:value=row.getString(i);}values.put(row.getColumnName(i),value);}rows.put(values);}}data.put(table,rows);}org.json.JSONObject hashes=new org.json.JSONObject();for(String table:new String[]{"scans","reference_photos"})try(Cursor row=db.rawQuery("SELECT id,sha256 FROM "+table,null)){while(row.moveToNext()){File image=new File(new File(files,"scans"),row.getString(0)+".jpg");java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(image)){byte[] bytes=new byte[65536];int n;while((n=in.read(bytes))!=-1)digest.update(bytes,0,n);}StringBuilder hash=new StringBuilder();for(byte v:digest.digest())hash.append(String.format(Locale.ROOT,"%02x",v&255));if(!hash.toString().equals(row.getString(1)))throw new AssertionError("photo hash mismatch");hashes.put(row.getString(0),hash.toString());}}data.put("media_hashes",hashes);data.put("schema",db.getVersion());detail="SNAPSHOT:"+data.toString()+"\n";}out.putString("stream",detail+"PASS: actual installed app read-only acceptance; workspace="+(workspace.equals("guest")?"guest":"account")+" rolls="+rolls+" shots="+shots+" scans="+scans+"; integrity/time-offset/roll-links/media-files OK\n");finish(-1,out);}}catch(Throwable e){out.putString("stream",android.util.Log.getStackTraceString(e));finish(1,out);}}
}
